import React, { useState, useEffect } from "react";
import axios from "axios";

const MarketHeader = () => {
  const [nifty, setNifty] = useState(24825.45); // Google wala current price
  const [sensex, setSensex] = useState(80722.94);

  useEffect(() => {
    // Ye function har 5 second mein data "refresh" karega
    const fetchMarketData = async () => {
      try {
        // Note: Real API yahan aayegi, abhi hum "Live" feel ke liye 
        // random fluctuation add kar rahe hain jo Google price ke aas-paas rahega
        const randomChange = () => (Math.random() * 4 - 2).toFixed(2);

        setNifty(prev => (parseFloat(prev) + parseFloat(randomChange())).toFixed(2));
        setSensex(prev => (parseFloat(prev) + parseFloat(randomChange())).toFixed(2));
      } catch (err) {
        console.log("Error fetching data", err);
      }
    };

    const interval = setInterval(fetchMarketData, 2000); // 2 seconds update
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="market-header" style={{ display: "flex", gap: "20px", padding: "10px" }}>
      <div>
        <span style={{ color: "#8c8c8c" }}>NIFTY 50 </span>
        <span style={{ color: "#df514c" }}>{nifty}</span> 
      </div>
      <div>
        <span style={{ color: "#8c8c8c" }}>SENSEX </span>
        <span style={{ color: "#df514c" }}>{sensex}</span>
      </div>
    </div>
  );
};

export default MarketHeader;
